package ch.lkmc.neutrodyne.playback.engine

import java.security.MessageDigest
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The MD0 corpus manifest (11 Testing, PLAN MD0 AC1). The manifest is generated by
 * `scripts/fixtures/corpus_reference.py` from the container structure of each file,
 * never by decoding it, so the counts below are an independent reference for
 * `FfmpegCorpusTest`. A file without a manifest entry, a manifest entry without a
 * file or a changed checksum fails here, so the corpus can never drift silently.
 */
class MediaCorpusTest {
    @Test
    fun `every corpus file has a manifest entry with a matching checksum`() {
        val manifest = readManifest()
        val directory = corpusDirectory()
        val files = directory.listFiles()?.filter { it.isFile && it.name != "corpus.json" } ?: emptyList()
        assertTrue("the corpus directory is empty: $directory", files.isNotEmpty())

        val entries = manifest.files.associateBy { it.file }
        for (file in files) {
            val entry = assertNotNull("${file.name} has no corpus.json entry", entries[file.name])
            assertEquals("${file.name} size", entry.bytes, file.length())
            assertEquals("${file.name} sha256", entry.sha256, sha256(file.readBytes()))
            assertTrue("${file.name} expects no samples", entry.expectedSamples > 0)
        }
        for (entry in manifest.files) {
            assertTrue(
                "${entry.file} is listed but missing",
                files.any { it.name == entry.file },
            )
        }
    }

    @Test
    fun `the manifest covers every format of MD0 AC1`() {
        val containers = readManifest().files.map { it.container }.toSet()

        assertEquals(
            setOf("mp3", "mp4", "ogg", "flac", "wav", "webm"),
            containers,
        )
    }

    @Test
    fun `chapter expectations carry titles and monotonic times`() {
        val withChapters = readManifest().files.filter { it.chapters.isNotEmpty() }

        assertEquals(2, withChapters.size)
        for (entry in withChapters) {
            var previous = 0L
            for (chapter in entry.chapters) {
                assertNotNull("${entry.file} has an untitled chapter", chapter.title)
                assertTrue(
                    "${entry.file} chapter ${chapter.title} starts before the previous one",
                    chapter.startMs >= previous,
                )
                previous = chapter.startMs
            }
        }
    }

    @Test
    fun `the manifest records the trim rule of every trimmed file`() {
        val trimmed = readManifest().files.filter { it.expectedSamples != it.decodedSamples }

        assertEquals(1, trimmed.size)
        assertEquals("fmp4_itag140_3s.mp4", trimmed.single().file)
        assertEquals("aac-fmp4-priming-1024", trimmed.single().trimRule)
    }

    private fun readManifest(): CorpusManifest {
        val text = corpusDirectory().resolve("corpus.json").readText()
        return Json.decodeFromString(CorpusManifest.serializer(), text)
    }

    private fun corpusDirectory() =
        java.io.File(
            System.getProperty("neutrodyne.moduleDir"),
            "src/test/resources/media",
        )

    private fun sha256(bytes: ByteArray): String =
        MessageDigest.getInstance("SHA-256").digest(bytes).joinToString("") { "%02x".format(it) }
}

@Serializable
data class CorpusManifest(
    val generatedBy: String,
    val corpus: String,
    val files: List<CorpusFile>,
)

@Serializable
data class CorpusFile(
    val file: String,
    val container: String,
    val codec: String,
    val sampleRate: Int,
    val channels: Int,
    val expectedSamples: Long,
    @SerialName("decodedSamples") val decodedSamples: Long? = null,
    val trimRule: String? = null,
    val chapters: List<CorpusChapter> = emptyList(),
    val bytes: Long,
    val sha256: String,
)

@Serializable
data class CorpusChapter(
    val startMs: Long,
    val endMs: Long? = null,
    val title: String? = null,
)
